mapper.select:
SELECT h.*, c.name customer_name, cg.group_name, s.sku_code, s.spec_name, COALESCE(sp.name, gsp.name) product_name FROM (SELECT l.id history_id, l.price_type source, l.price_id, ap.customer_id, gp.group_id, COALESCE(ap.sku_id, tp_price.sku_id) sku_id, gp.spu_id, l.operation_type, l.operator, l.created_at operated_at, l.before_data, l.after_data, COALESCE(ap.unit_price, gp.unit_price, tp_price.unit_price) current_unit_price, COALESCE(ap.effective_from, gp.effective_from, tp_price.start_at) current_effective_from, COALESCE(ap.effective_to, gp.effective_to, tp_price.end_at) current_effective_to, COALESCE(ap.deleted, gp.deleted, tp_price.deleted, TRUE) current_deleted FROM xsy_price_operation_log l LEFT JOIN xsy_customer_agreement_price ap ON l.price_type = 'AGREEMENT' AND ap.id = l.price_id LEFT JOIN xsy_customer_group_price gp ON l.price_type = 'CUSTOMER_GROUP' AND gp.id = l.price_id LEFT JOIN xsy_pricing_time_price tp_price ON l.price_type = 'TIME_PRICE' AND tp_price.id = l.price_id -- 只展示仍在用的三种价格来源；已下线来源的日志 append-only 无法删除，这里过滤掉。 WHERE l.price_type IN ('AGREEMENT', 'CUSTOMER_GROUP', 'TIME_PRICE')) h LEFT JOIN xsy_customer c ON c.id = h.customer_id LEFT JOIN xsy_customer_group cg ON cg.id = h.group_id LEFT JOIN xsy_product_sku s ON s.id = h.sku_id LEFT JOIN xsy_product_spu sp ON sp.id = s.spu_id LEFT JOIN xsy_product_spu gsp ON gsp.id = h.spu_id
AND h.source = #{query.source} AND h.customer_id = #{query.customerId} AND h.group_id = #{query.groupId} AND h.sku_id = #{query.skuId} AND h.operation_type = #{query.operationType} AND h.operated_at >= #{query.operatedFrom} AND h.operated_at <= #{query.operatedTo}
AND COALESCE(h.current_effective_to, 'infinity'::timestamptz) > #{query.effectiveFrom}
AND h.current_effective_from < #{query.effectiveTo}
ORDER BY h.operated_at DESC, h.history_id DESC, h.source
